package com.bank.portal.domain; import jakarta.persistence.*; import java.time.LocalDateTime; import lombok.*;
@Entity @Table(name="customer_onboarding_requests") @Getter @Setter @NoArgsConstructor public class CustomerOnboardingRequest extends BaseEntity { @Column(nullable=false) private String name; @Column(nullable=false,unique=true) private String email; @Column(nullable=false) private String mobileNumber; @Column(nullable=false,unique=true) private String panNumber; @Enumerated(EnumType.STRING) @Column(nullable=false) private OnboardingRequestStatus status; private String reviewComment; private String reviewedBy; private LocalDateTime reviewedAt; }
